  var _g = function(e){ var o = states[e]; return o ? o.state : undefined; };
  var choice = _g('input_select.inkbird_dashboard_model') || 'Auto';
  var profile = _g('sensor.inkbird_int_14_configured_model_profile') || '';
  var model = _g('sensor.inkbird_int_14_configured_model') || '';
  var bw = choice === 'INT-14-BW' || (choice === 'Auto' && (profile === 'int14_bw' || (model.includes('14-BW') && !model.includes('14S'))));
  var eCtrl   = 'sensor.bbq_probe_' + n + '_control_temperature';
  var eDirect = pfx + '_probe_' + n + '_' + (bw ? 'internal' : 'food_4') + '_temperature';
  var eAlt    = pfx + '_probe_' + n + '_' + (bw ? 'internal' : 'food_1') + '_temperature';
  var _gVal = function(e){ var o = states[e]; return (o && o.state !== 'unknown' && o.state !== 'unavailable' && o.state !== '') ? parseFloat(o.state) : NaN; };
  var t = _gVal(eCtrl);
  if (isNaN(t)) t = _gVal(eDirect);
  if (isNaN(t)) t = _gVal(eAlt);
  var s = _g(eState) || 'idle';
  var col = s==='ready' ? '#56c271' : s==='close' ? '#ff6a2c' : s==='heating' ? '#f2b441' : '#77695c';
  var g = parseFloat(_g(eTarget));
  var amb = 22, connected = !isNaN(t);
  var pct = connected ? Math.max(0, Math.min(1,(t-amb)/(g-amb))) : 0;
  var R=52, C=2*Math.PI*R, ARC=0.75;
  var dash=(C*ARC*pct).toFixed(1)+' '+C;
  var uf = (_g('input_select.inkbird_unit')||'').indexOf('F') >= 0;
