custom_fields.status:
[[[
  var tr = states['sensor.inkbird_int_14_active_transport'];
  var bc = states['binary_sensor.inkbird_int_14_ble_connected'];
  var t  = tr ? tr.state : 'unknown';
  var map = {
    ble:        ['Bluetooth', 'live'],
    ble_waiting:['Bluetooth', 'wait'],
    wifi:       ['Wi-Fi',     'live'],
    wi_fi:      ['Wi-Fi',     'live'],
    local_lan:  ['LAN',       'live'],
    lan:        ['LAN',       'live'],
    cloud:      ['History',   'history'],
    none:       ['no link',   'down'],
    unknown:    ['no link',   'down'],
    unavailable:['no link',   'down']
  };
  var m = map[t] || [t.replace(/_/g,' '), 'live'];
  var how = m[0], mode = m[1];
  if (mode === 'live' && t.indexOf('ble') === 0 && !(bc && bc.state === 'on')) mode = 'wait';
  var col  = mode === 'live' ? '#56c271' : mode === 'history' ? '#4f98f0' : mode === 'wait' ? '#f2b441' : '#e8503a';
  var word = mode === 'live' ? 'Live' : mode === 'history' ? 'History' : mode === 'wait' ? 'Connecting' : 'Offline';
  var pulse = mode === 'wait' ? 'animation:inkbird-pulse 1.4s ease-in-out infinite' : '';
  var bs = states['sensor.overig_inkbird_int_14_base_battery'];
  var b = bs ? bs.state : undefined;
  b = (b === undefined || b === 'unknown' || b === 'unavailable') ? '\u2014' : b + '%';
  var quality = states['sensor.inkbird_int_14_battery_report_quality'];
  var suspect = quality && /suspect|degrad/i.test(quality.state);
  var soundId = Object.keys(states).find(function(id){ return id.indexOf('switch.')===0 && id.indexOf('inkbird')>=0 && /(sound|mute)/.test(id); });
  var se = soundId ? states[soundId] : null;
  var ss = se || states['binary_sensor.inkbird_int_14_sound_enabled'];
  var sound = !ss ? '\ud83d\udd07 \u2014' : ss.state === 'on' ? '\ud83d\udd0a On' : ss.state === 'off' ? '\ud83d\udd07 Off' : '\ud83d\udd07 \u2014';
  return `<style>@keyframes inkbird-pulse{0%,100%{opacity:1}50%{opacity:.25}}</style>
  <div style="display:flex;gap:8px;align-items:center;justify-content:flex-end;flex-wrap:wrap;font-family:system-ui">
